  label = "countries",
  cities = DEFAULT_CITIES,
  accent = "#3B5BFD",
  ink,
  background,
  fontFamily = manrope,
  fontWeight = 400,
  sweep = LIGHT_SPAN,
  scale = 1,
  delay = 0,
  grain = true,
  theme = "dark",
  speed = 1,
