  const t = Math.max(0, useSceneFrame() - delay) * speed;
  const { width: W, height: H } = useSceneConfig();
  const u = Math.min(W / 1280, H / 720);
  const p = THEMES[theme];
  const fg = ink ?? p.fg;
  const bg = background ?? p.bg;
  const done = LIGHT_AT + sweep + 6;

