      const cell = snap(city.lon, city.lat);
      if (cell < 0 || seen.has(cell)) return;
      seen.add(cell);
      const x = (city.lon + 180) / 360;
      out.push({
        cell,
        at: LIGHT_AT + x * sweep + (hash(i + 0.7) - 0.5) * 8,
