      const m = meshAt(
        c / COLS,
        r0 / ROWS,
        pal.bg,
        pal.colors,
        drift,
        pal.reach,
      );
      const tint: [number, number, number] = [
        m[0] + (liftTo[0] - m[0]) * p.lift,
        m[1] + (liftTo[1] - m[1]) * p.lift,
        m[2] + (liftTo[2] - m[2]) * p.lift,
      ];
      dots.push(
        <circle
          key={idx}
          cx={x}
          cy={y}
          r={r * (0.7 + 0.3 * a)}
          fill={toHex(tint)}
          opacity={a * p.dotAlpha}
        />,
      );
    }
  }

  let shown = 0;
  for (const l of lit) if (t >= l.at) shown++;
  const value = lit.length
    ? Math.round((count * shown) / lit.length)
    : Math.round(count);
  const numIn = interpolate(t, [LIGHT_AT - 8, LIGHT_AT + 8], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const labIn = interpolate(t, [LIGHT_AT, LIGHT_AT + 16], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });

  return (
    <AbsoluteFill style={{ background: bg, overflow: "hidden" }}>
      <ScaleLayer scale={scale}>
        <AbsoluteFill
          style={{
            transform: `scale(${zoom})${glide(zooming)}`,
            transformOrigin: "50% 50%",
          }}
        >
          <svg
            width={W}
            height={H}
            style={{ position: "absolute", inset: 0 }}
            aria-hidden
          >
            {dots}
            {accents}
          </svg>
          <div
            style={{
              position: "absolute",
              left: 0,
              width: W,
              top: mapY + mapH + gap,
              display: "flex",
              justifyContent: "center",
              alignItems: "baseline",
              gap: 18 * u,
              whiteSpace: "nowrap",
            }}
          >
            <span
              style={{
                fontFamily,
                fontWeight,
                fontSize: numSize,
                lineHeight: 0.9,
                letterSpacing: "-0.04em",
                color: fg,
                fontVariantNumeric: "tabular-nums",
                opacity: numIn,
                transform: `translateY(${(1 - numIn) * 12 * u}px)`,
                display: "inline-block",
                minWidth: `${String(Math.round(count)).length * 0.6}em`,
                textAlign: "right",
              }}
            >
              {value}
            </span>
            <span
              style={{
                fontFamily,
                fontWeight: 500,
                fontSize: 30 * u,
                letterSpacing: "-0.015em",
                color: p.muted,
                opacity: labIn,
                transform: `translateY(${(1 - labIn) * 8 * u}px)`,
                display: "inline-block",
              }}
            >
              {label}
            </span>
          </div>
        </AbsoluteFill>
      </ScaleLayer>

      <AbsoluteFill
        style={{
          background: `radial-gradient(ellipse 80% 80% at 50% 50%, transparent 62%, ${bg} 100%)`,
          opacity: 0.6,
          pointerEvents: "none",
        }}
      />
      {grain ? <Grain opacity={p.grain} /> : null}
    </AbsoluteFill>
  );
}

