const ELEMENT_PROP_KEYS = new Set(["theme","label","count","fontWeight","sweep","accent","fontFamily","ink","background","scale","delay","grain","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  label: "countries",
  count: 142,
  fontWeight: 400,
  sweep: 66,
  accent: "#3B5BFD",
